static uint32_t native_gpu_reserve_hint(uint32_t required) {
    uint32_t capacity = 16u;
    while (capacity < required)
        capacity = capacity > UINT32_MAX / 2u ? UINT32_MAX : capacity * 2u;
    return capacity;
}
